messages.content:
{
  "message": "I can help. To restore excellent mobile data speed, I’ll check both your account/line status (data limits, roaming, suspensions) and your phone’s settings (signal, network mode, Data Saver, VPN). I’ll need a couple of things from you and some quick checks on your phone.",
  "next_steps_overview": [
    "Verify your account so I can check your line’s status and data usage.",
    "Run a few quick on-device checks to pinpoint why speeds are slow or dropping."
  ],
  "need_verification": "Please identify your account using ONE of the following so I can look up your line:",
  "acceptable_identifiers": [
    "The phone number of the affected line (preferred)",
    "Customer ID",
    "Full name AND date of birth (YYYY-MM-DD)"
  ],
  "clarifying_questions": [
    "Are you currently traveling outside your usual area (possibly roaming)?",
    "When the internet stops, do calls and regular texts still work?",
    "Roughly how long has this been happening?"
  ],
  "on_device_checks": [
    {
      "action": "check_status_bar",
      "why": "Confirms signal strength, network type (5G/4G/3G), and whether anything like Airplane Mode, Data saver, or VPN might be affecting data.",
      "what_to_report_back": [
        "Signal bars shown (📶¹/²/³/⁴ or '📵 No Signal')",
        "Network type shown (5G/4G/3G/2G)",
        "If you see '📱 Data Enabled' or '📵 Data Disabled'",
        "If you see '✈️ Airplane Mode' or '🔽 Data Saver' or '🔒 VPN Connected'"
      ]
    },
    {
      "action": "run_speed_test",
      "why": "Measures current mobile data performance. Anything below 'Excellent' indicates an issue we can address.",
      "what_to_report_back": [
        "The result rating: 'unknown', 'very poor', 'poor', 'fair', 'good', or 'excellent'",
        "If it fails, tell me the error (e.g., 'no connection')"
      ]
    },
    {
      "action": "check_network_mode_preference",
      "why": "If set to older modes (2G/3G), speeds will be slow. We want 4G/5G preferred.",
      "what_to_report_back": [
        "Current setting (e.g., '4g_5g_preferred', '4g_only', '3g', '2g')"
      ]
    },
    {
      "action": "check_data_restriction_status",
      "why": "Data Saver can throttle or block background data and make apps feel slow.",
      "what_to_report_back": [
        "Whether Data Saver is ON or OFF"
      ]
    },
    {
      "action": "check_vpn_status",
      "why": "A VPN can severely reduce speed if the server is slow or far away.",
      "what_to_report_back": [
        "Whether VPN is connected or not"
      ]
    }
  ],
  "note_on_outcomes": "Once you share your phone number (or other identifier) and the results above, I’ll immediately check your line for any data cap reached, throttling, roaming configuration, or suspension, and then guide you through precise fixes (e.g., enabling roaming if you’re outside your home network, turning off Data Saver, switching to 4G/5G preferred, disconnecting a slow VPN, or refueling data if you’ve hit your plan limit). Our target is an 'Excellent' speed test result."
}

