{
  "explanation": "I can help. To fix No Service, we need to rule out two buckets: (1) account/line issues (e.g., suspension or SIM provisioning) and (2) device/network settings (airplane mode, SIM, network mode, APN). I’ll look up your line status while you run a few quick checks on the phone so we don’t waste time.",
  "what_i_need_from_you": {
    "identity_for_lookup": "Please provide ONE of the following so I can check your line: (a) the phone number with no service, or (b) your customer ID, or (c) your full name AND date of birth (YYYY-MM-DD).",
    "a_few_context_questions": [
      "When did this start, and did anything change right before it (travel, SIM swap, plan change, software update)?",
      "Are you currently traveling outside your usual area or country?",
      "Do you have other lines/devices on the same account, and are they working?"
    ]
  },
  "quick_checks_on_your_phone": [
    {
      "step": "Check status bar",
      "why": "Confirms if Airplane Mode is on and if the phone sees any signal at all.",
      "how": "Use check_status_bar and tell me what you see: any airplane icon, signal bars, network type (5G/4G), and whether mobile data shows enabled/disabled."
    },
    {
      "step": "Airplane Mode reset",
      "why": "Forces all radios to re-register to the network.",
      "how": "Toggle Airplane Mode ON, wait 10 seconds, then OFF (use toggle_airplane_mode)."
    },
    {
      "step": "SIM status",
      "why": "A missing or locked SIM causes No Service.",
      "how": "Run check_sim_status. If it shows Missing, reseat the SIM (use reseat_sim_card). If it shows Locked (PIN/PUK), stop and tell me—I'll escalate appropriately."
    },
    {
      "step": "Network mode",
      "why": "Being stuck on 2G/3G can prevent service in many areas.",
      "how": "Run check_network_mode_preference. If it’s 2G/3G, set it to 4g_5g_preferred (use set_network_mode_preference)."
    },
    {
      "step": "Mobile data switch",
      "why": "Some phones show No Service-like behavior if data is off and Wi‑Fi is also off.",
      "how": "Run check_network_status and, if Mobile Data is disabled, turn it ON (use toggle_data)."
