messages.content:
{
  "summary": "Your VPN is ON and its server performance is poor. A slow VPN can cap your speed even on a strong 5G signal. Disconnecting it is the fastest way to remove that bottleneck.",
  "what_to_do_now_on_your_phone": [
    {
      "action": "disconnect_vpn()",
      "reason": "Removes the slow VPN tunnel that’s limiting throughput."
    },
    {
      "action": "wait_10_15_seconds",
      "reason": "Lets the phone re-route traffic directly over the mobile network."
    },
    {
      "action": "run_speed_test()",
      "reason": "Verify performance after removing the VPN. We’re aiming for Excellent."
    }
  ],
  "if_result_is_excellent": "Great — we’ve resolved the bottleneck. You can keep VPN off for maximum speed, or only enable it when needed.",
  "if_result_is_not_excellent": [
    {
      "step": "toggle_airplane_mode_on_then_off",
      "reason": "Forces a fresh network attach to the roaming partner."
    },
    {
      "step": "reboot_device()",
      "reason": "Clears any lingering network stack issues."
    },
    {
      "step": "optional_test",
      "do": "set_network_mode_preference(mode=\"4g_only\")",
      "reason": "Sometimes 5G cells are congested; testing 4G-only can improve consistency. If no improvement, switch back to 4g_5g_preferred."
    },
    {
      "step": "run_speed_test() again after each change"
    }
  ],
  "why_these_steps": [
    "VPN with poor performance is a known cause of good-but-not-excellent speeds.",
    "Airplane Mode toggle and a reboot refresh your network registration.",
    "Testing 4G-only is a diagnostic step allowed by your device settings to see if a different radio path performs better."
  ],
  "please_share_back": [
    "The new run_speed_test() result after disconnecting the VPN.",
    "If still not Excellent, share the results after the Airplane Mode toggle and/or reboot, and confirm if trying 4g_only changed anything."
  ]
}

