  "instructions": [
    {
      "step": "Check status bar",
      "how": "Look at the top of your screen and tell me exactly what you see: any airplane icon, how many signal bars, and the network type shown (5G/4G/LTE/3G/2G). Also note if you see a mobile data icon.",
      "why": "Confirms you have service, data is enabled, and whether you’re on a fast network type."
    },
    {
      "step": "Check network status",
      "how": "Open your phone’s network settings and confirm: Mobile data is ON, Data roaming (only if you’re traveling) is ON, and signal strength (none/poor/fair/good/excellent).",
      "why": "Ensures data is actually enabled and whether roaming needs to be on."
    },
    {
      "step": "Network mode preference",
      "how": "In mobile network settings, set Preferred network to 4G/5G (often called 5G On/Auto, 5G/LTE/3G/2G Auto, or 4G/5G preferred). Avoid 2G/3G-only modes.",
