      "Phone number of the line with the MMS issue",
      "Customer ID",
      "Full name AND date of birth (YYYY-MM-DD)"
    ],
    "diagnostic_questions": [
      "Are you currently traveling outside your usual coverage area/country?",
      "Can you make and receive regular calls and SMS texts right now?",
      "When you try to send an MMS, do you get an error message? If yes, what does it say?",
      "About when did this start, and did anything change recently (new phone/SIM, APN edits, app change)?"
    ]
  },
  "quick_checks_now": [
    {
      "step": "Check status bar basics",
      "how": "Look at the top of your screen.",
      "tell_me": "Do you see any Airplane mode icon? What’s the signal strength (no bars/1/2/3/4)? Do you see 5G/4G/LTE/3G/2G? Is mobile data icon present?",
      "why": "Airplane mode or no signal stops MMS. Being on 2G is also not suitable for MMS."
    },
    {
      "step": "Verify mobile data works (not just Wi‑Fi)",
      "how": "Temporarily turn Wi‑Fi OFF. Then open a website in your browser.",
      "tell_me": "Did the page load over mobile data?",
      "why": "MMS requires mobile data. If mobile data isn’t working, MMS won’t send."
    },
    {
      "step": "Check Wi‑Fi Calling",
      "how": "Open Phone settings > Wi‑Fi Calling. If it’s ON, note that.",
      "tell_me": "Is Wi‑Fi Calling ON?",
      "why": "Some configurations can interfere with MMS. We may turn it OFF temporarily to test."
    },
