    "why_needed": "Required to check your line status, data usage, and roaming settings on our side."
  },
  "questions": [
    "When you try to send a picture message, do you see any specific error (e.g., ‘Not sent’, ‘Tap to retry’), or does it just spin?",
    "Can you place a normal voice call right now?",
    "With Wi‑Fi turned OFF, can you open a webpage in your browser (this checks mobile data)?",
    "Are you currently traveling outside your usual area or internationally?",
    "Do you see 4G/LTE/5G in the status bar, or does it show 2G/3G, or no signal?",
    "Have you recently changed SIM, reset network settings, or installed a VPN?"
  ],
  "quick_fix_steps": [
    {
      "step": "Confirm service and mobile data",
      "actions": [
        "Make sure Airplane Mode is OFF.",
        "Ensure Mobile Data is ON (not just Wi‑Fi).",
        "If Data Saver is ON, turn it OFF."
      ],
      "reason": "MMS requires active cellular service and mobile data (any speed). Data Saver can interfere."
    },
    {
      "step": "Use a modern network mode",
      "actions": [
        "Set Network Mode/Preferred Network to 4G/5G (avoid 2G/3G-only modes)."
      ],
      "reason": "2G is generally not suitable for MMS; 4G/5G ensures adequate data connectivity."
    },
    {
      "step": "Turn OFF Wi‑Fi Calling temporarily",
      "actions": [
        "Disable Wi‑Fi Calling in your phone settings for this test."
      ],
      "reason": "In some configurations, Wi‑Fi Calling can interfere with MMS routing."
    },
    {
      "step": "Reset APN to default, then reboot",
      "actions": [
        "Open Mobile Network > Access Point Names (APN) and choose ‘Reset to default’.",
        "Restart (reboot) your phone."
      ],
      "reason": "A missing/incorrect MMSC URL in the APN is a very common MMS failure. Reset + reboot restores correct settings."
    },
    {
      "step": "Confirm messaging app permissions",
      "actions": [
        "Open your messaging app’s App Info > Permissions.",
        "Allow SMS and Storage/Photos & Media."
      ],
      "reason": "The app needs SMS and storage access to send/attach pictures."
    },
    {
      "step": "Test MMS",
      "actions": [
        "Turn OFF Wi‑Fi just for the test (to force mobile data).",
        "Send a picture message to your own number and report the result."
      ],
      "reason": "This validates MMS over mobile data after the fixes."
    }
  ],
  "what_happens_next": "Once you share your identifying info, I’ll check your line status, data usage (to ensure you haven’t hit a data limit that would block data/MMS), and roaming settings. If roaming needs to be enabled or there’s a suspension/block, I’ll address it. Meanwhile, the steps above often resolve MMS within a few minutes.",
  "note": "Please let me know the results of each step (especially any errors you see), and provide your phone number or other ID so I can check the line on our side."
}

