{
  "message": "You now have strong 5G with data enabled, so the most common remaining MMS blockers are APN/MMSC settings, Wi‑Fi Calling conflicts, app permissions, or a lingering registration issue. We’ll verify each quickly.",
  "steps": [
    {
      "title": "Quick data check (confirms general internet over mobile data)",
      "why": "MMS needs working mobile data. If web browsing works, data is fine and we focus on MMS-specific settings.",
      "instructions": [
        "Keep Wi‑Fi OFF.",
        "Open a simple website like example.com in your browser. Confirm it loads.",
        "If it does NOT load: check that any VPN is OFF (check_vpn_status; disconnect_vpn if connected) and make sure Data Saver is OFF (check_data_restriction_status; toggle_data_saver_mode OFF), then try example.com again."
      ]
    },
    {
      "title": "APN/MMSC settings",
      "why": "A missing/incorrect MMSC URL is a very common reason MMS fails even when data works, especially while roaming.",
      "instructions": [
        "Run check_apn_settings.",
        "If the MMSC URL is missing or looks blank/incorrect, run reset_apn_settings.",
        "Important: After resetting APN, run reboot_device so the changes take effect.",
        "After the reboot, try sending your picture again (with Wi‑Fi still OFF)."
      ]
    },
    {
      "title": "Wi‑Fi Calling",
      "why": "Some networks don’t support MMS over Wi‑Fi Calling; turning it OFF avoids conflicts.",
      "instructions": [
        "Run check_wifi_calling_status.",
        "If Wi‑Fi Calling is ON, toggle_wifi_calling OFF and retry sending the MMS."
      ]
    },
    {
      "title": "Messaging app permissions",
      "why": "The Messages app needs SMS and Storage/Photos permissions to attach and send media.",
      "instructions": [
        "Run check_app_permissions(app_name=\"messaging\").",
        "If SMS or Storage/Photos isn’t granted, use grant_app_permission for those, then retry MMS."
      ]
    },
    {
      "title": "Built‑in MMS diagnostic",
      "why": "This can pinpoint remaining blockers if the above look fine.",
      "instructions": [
        "Run can_send_mms and let me know the result."
      ]
    }
  ],
  "please_share": [
    "Does example.com load over mobile data (with Wi‑Fi OFF)?",
    "What does check_apn_settings show for the MMSC URL?",
    "Is Wi‑Fi Calling ON or OFF?",
    "Which permissions does the Messages app have for SMS and Storage/Photos?",
    "What does can_send_mms report?",
    "Are you on iPhone or Android? I can provide button‑by‑button steps if you tell me which."
  ],
  "notes": [
    "Resetting APN requires a reboot to apply.",
    "None of these steps will delete your data.",
    "Roaming is enabled on your line and you have about 1.9 GB available now."
  ]
}

